// mouseover/mouseout BUBBLINGUJA - wystrzeliwuja PONOWNIE przy kazdym
// przejsciu kursora miedzy WEWNETRZNYMI elementami danego kontenera
// (np. z <div> na zagniezdzony w nim <span>), co powoduje 'miganie'
// efektu (np. tla) przy kazdym takim przejsciu.
//
// mouseenter/mouseleave NIE bubbinguja - reaguja WYLACZNIE na faktyczne
// wejscie/wyjscie z CALEGO obszaru elementu (wraz z jego dziecmi),
// ignorujac wewnetrzne przejscia. Dlatego dla prostych efektow hover sa
// zazwyczaj wlasciwszym, bardziej stabilnym wyborem.

function opiszPrzycisk(button) {
  if (button === 0) return "lewy";
  if (button === 1) return "srodkowy";
  if (button === 2) return "prawy";
  return "nieznany";
}

console.log(opiszPrzycisk(0), opiszPrzycisk(1), opiszPrzycisk(2), opiszPrzycisk(5));

function odlegloscOdPoczatku(x, y) {
  return Math.sqrt(x * x + y * y);
}

console.log(odlegloscOdPoczatku(3, 4));

function odleglosc(a, b) {
  return Math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2);
}
function symulujMousemove(pozycje) {
  const wyniki = [];
  for (let i = 1; i < pozycje.length; i++) {
    wyniki.push(odleglosc(pozycje[i - 1], pozycje[i]));
  }
  return wyniki;
}

console.log(symulujMousemove([[0, 0], [3, 4], [3, 0]]));

const stanHover = {
  aktywny: false,
  wejdz() { this.aktywny = true; },
  wyjdz() { this.aktywny = false; }
};

stanHover.wejdz();
console.log(stanHover.aktywny);
stanHover.wyjdz();
console.log(stanHover.aktywny);

function symulujKlikniecia(typy) {
  return typy.filter(t => t === "dblclick").length;
}

console.log(symulujKlikniecia(["click", "dblclick", "click", "dblclick", "dblclick"]));

function jestWewnatrzObszaru(x, y, szerokosc, wysokosc) {
  return x >= 0 && x <= szerokosc && y >= 0 && y <= wysokosc;
}

console.log(jestWewnatrzObszaru(50, 30, 100, 100));
console.log(jestWewnatrzObszaru(150, 30, 100, 100));

class SledzenieKursora {
  constructor() {
    this.historia = [];
  }
  dodaj(x, y) {
    this.historia.push({ x, y });
  }
  ostatnia() {
    return this.historia[this.historia.length - 1];
  }
}

const sledzenie = new SledzenieKursora();
sledzenie.dodaj(10, 20);
sledzenie.dodaj(15, 25);
console.log(sledzenie.ostatnia());

function rozroznijBubbling(typZdarzenia) {
  return typZdarzenia === "mouseover" || typZdarzenia === "mouseout";
}

console.log(rozroznijBubbling("mouseover"));
console.log(rozroznijBubbling("mouseenter"));

function policzKlikniecia(zdarzenia) {
  return zdarzenia.reduce((acc, e) => {
    acc[e.button] = (acc[e.button] || 0) + 1;
    return acc;
  }, {});
}

console.log(policzKlikniecia([{ button: 0 }, { button: 2 }, { button: 0 }]));

function throttle(fn, limit) {
  let ile = 0;
  return function (...args) {
    ile++;
    if (ile % limit === 0) return fn(...args);
    return "pominiete";
  };
}

const h = throttle((x) => "wykonano:" + x, 3);
console.log(h(1), h(2), h(3), h(4));

function odleglosc(a, b) {
  return Math.hypot(a.x - b.x, a.y - b.y);
}
function najwiekszaOdlegosc(punkty) {
  let maks = 0;
  for (let i = 1; i < punkty.length; i++) {
    const d = odleglosc(punkty[i - 1], punkty[i]);
    if (d > maks) maks = d;
  }
  return maks;
}

console.log(najwiekszaOdlegosc([{ x: 0, y: 0 }, { x: 3, y: 4 }, { x: 3, y: 4 }]));

function czyPodwojneKlikniecie(czas1, czas2, prog) {
  return Math.abs(czas2 - czas1) <= prog;
}

console.log(czyPodwojneKlikniecie(100, 250, 300));
console.log(czyPodwojneKlikniecie(100, 500, 300));

const symulujacyPrzeciaganie = {
  start: null,
  zacznij(x, y) {
    this.start = { x, y };
  },
  zakoncz(x, y) {
    return { dx: x - this.start.x, dy: y - this.start.y };
  }
};

symulujacyPrzeciaganie.zacznij(10, 10);
console.log(symulujacyPrzeciaganie.zakoncz(25, 18));

function grupujPoPrzycisku(kliknienia) {
  const mapa = new Map();
  kliknienia.forEach((btn) => {
    mapa.set(btn, (mapa.get(btn) || 0) + 1);
  });
  return mapa;
}

console.log(grupujPoPrzycisku([0, 2, 0, 0, 2]));

function jestSzybkimRuchem(dystans, czasMs, prog) {
  return dystans / czasMs > prog;
}

console.log(jestSzybkimRuchem(100, 50, 1));
console.log(jestSzybkimRuchem(10, 50, 1));

function sciezkaDoStringa(punkty) {
  return punkty.map(p => p.x + "," + p.y).join(" -> ");
}

console.log(sciezkaDoStringa([{ x: 0, y: 0 }, { x: 5, y: 5 }, { x: 10, y: 0 }]));

function symulujDetail(ilosc) {
  if (ilosc === 1) return "pojedyncze";
  if (ilosc === 2) return "podwojne";
  if (ilosc === 3) return "potrojne";
  return "wiele";
}

console.log(symulujDetail(1), symulujDetail(2), symulujDetail(3), symulujDetail(7));

function kierunekScrolla(deltaY) {
  if (deltaY > 0) return "dol";
  if (deltaY < 0) return "gora";
  return "brak";
}

console.log(kierunekScrolla(120), kierunekScrolla(-50), kierunekScrolla(0));

function symulujDrag(punkty) {
  let suma = 0;
  for (let i = 1; i < punkty.length; i++) {
    suma += Math.hypot(punkty[i].x - punkty[i - 1].x, punkty[i].y - punkty[i - 1].y);
  }
  return suma;
}

console.log(symulujDrag([{ x: 0, y: 0 }, { x: 3, y: 0 }, { x: 3, y: 4 }]));

function jestModyfikatoremWcisniety(ctrl, shift, alt) {
  return ctrl || shift || alt;
}

console.log(jestModyfikatoremWcisniety(false, false, false));
console.log(jestModyfikatoremWcisniety(false, true, false));

function symulujScrollDoKonca(pozycjaY, wysokoscStrony, prog) {
  return pozycjaY + prog >= wysokoscStrony;
}

console.log(symulujScrollDoKonca(950, 1000, 100));
console.log(symulujScrollDoKonca(100, 1000, 100));

function sumujDeltaY(zdarzeniaWheel) {
  return zdarzeniaWheel.reduce((suma, e) => suma + e.deltaY, 0);
}

console.log(sumujDeltaY([{ deltaY: 100 }, { deltaY: -30 }, { deltaY: 50 }]));

